// =========================================================================
// PURELOX KAPAZITÄTS-PRÄSENTATION GENERATOR v3
// Layout 1:1 aus Original-Template übernommen (exakte EMU-Maße)
// =========================================================================
const pptxgen = require("pptxgenjs");
const fs = require("fs");

const CONFIG_FILE = process.argv[2] || "kapazitaet_config.json";
let config;
try {
  config = JSON.parse(fs.readFileSync(CONFIG_FILE, "utf8"));
} catch(e) {
  config = {
    titelseite: {
      headline: "Portfolio Kapazitätsplanung",
      subheadline: "Übersicht FTE & Projektphasen Q2/2026 – Q2/2027",
      praesentationFuer: "Musterkunde GmbH",
      datum: "Mai 2026",
      ersteller: "BOOST – Customer Solutions Team"
    },
    projekte: [
      { name: "ETE",  phasen: {"Apr 26":"p","Mai 26":"p","Jun 26":"k","Jul 26":"k","Aug 26":"t","Sep 26":"t","Okt 26":"g"}, fte: {"Apr 26":0.5,"Mai 26":1,"Jun 26":1.5,"Jul 26":1.5,"Aug 26":1,"Sep 26":1,"Okt 26":0.5} },
      { name: "HOAG", phasen: {"Mai 26":"p","Jun 26":"k","Jul 26":"k","Aug 26":"k","Sep 26":"t","Okt 26":"g"},              fte: {"Mai 26":0.5,"Jun 26":1,"Jul 26":1,"Aug 26":1.5,"Sep 26":1,"Okt 26":0.5} },
      { name: "HALO", phasen: {"Jun 26":"p","Jul 26":"p","Aug 26":"k","Sep 26":"k","Okt 26":"t","Nov 26":"t","Dez 26":"g"},  fte: {"Jun 26":0.5,"Jul 26":0.5,"Aug 26":1,"Sep 26":1.5,"Okt 26":1,"Nov 26":1,"Dez 26":0.5} },
      { name: "IBSL", phasen: {"Aug 26":"p","Sep 26":"k","Okt 26":"k","Nov 26":"t","Dez 26":"g"},                           fte: {"Aug 26":0.5,"Sep 26":1,"Okt 26":1.5,"Nov 26":1,"Dez 26":0.5} },
      { name: "MBSL", phasen: {"Sep 26":"p","Okt 26":"k","Nov 26":"k","Dez 26":"t","Jan 27":"g"},                           fte: {"Sep 26":0.5,"Okt 26":1,"Nov 26":1,"Dez 26":1,"Jan 27":0.5} },
      { name: "SPMI", phasen: {"Okt 26":"p","Nov 26":"k","Dez 26":"k","Jan 27":"t","Feb 27":"g"},                           fte: {"Okt 26":0.5,"Nov 26":1,"Dez 26":1.5,"Jan 27":1,"Feb 27":0.5} },
    ]
  };
}

// =========================================================================
// ASSETS (eingebettet – direkt aus Template-Medien extrahiert)
// =========================================================================
const LOGO_B64   = "image/png;base64,";
const FOOTER_B64 = "image/jpeg;base64,";
const TITLEBG_B64   = "image/jpeg;base64,";
const LOGOWHITE_B64 = "image/png;base64,";
const CLOUDS_B64    = "image/png;base64,";
const BG_B64     = "image/jpeg;base64,";

// =========================================================================
// EXAKTE LAYOUT-MASSE (aus slideMaster1.xml gemessen, in Zoll)
// Foliengrösse: 10" × 5.625" (16:9)
// =========================================================================
const L = {
  // Slide
  W: 10, H: 5.625,

  // Navy-Balken oben (volle Breite)
  navyX: 0, navyY: 0, navyW: 10, navyH: 0.551,

  // Weißer Hintergrundblock hinter Logo (überdeckt navy rechts)
  logoBoxX: 1.429, logoBoxY: 0, logoBoxW: 8.572, logoBoxH: 0.630,

  // Logo (rId45 = image1.png)
  logoX: 8.480, logoY: 0.170, logoW: 1.221, logoH: 0.373,

  // Titel-Textbox
  titleX: 0.354, titleY: 0.158, titleW: 7.480, titleH: 0.315,

  // Content-Bereich (ab hier Inhalt)
  contentX: 0.354, contentY: 1.024,
  contentW: 9.240, contentH: 4.048,

  // Footer-Verlaufsstreifen (rId46 = image2.jpg)
  footerX: 0, footerY: 5.354, footerW: 10, footerH: 0.047,

  // Copyright-Text
  copyrightX: 0.354, copyrightY: 5.433, copyrightW: 1.142, copyrightH: 0.114,

  // Seitenzahl
  pageNumX: 8.929, pageNumY: 5.433, pageNumW: 0.740, pageNumH: 0.102,
};

// CI Farben
const CI = {
  navy:    "002F5E",
  white:   "FFFFFF",
  bgLight: "E8EEF6",   // hellblauer Inhaltshintergrund (wie im Template slide 9/11)
  text:    "002F5E",   // Navy für Titeltext
  phase: {
    p: { bg: "0A55B9", label: "Pflichtenheft" },
    k: { bg: "288CE1", label: "Konfiguration" },
    t: { bg: "C355D7", label: "Test"          },
    g: { bg: "CD145A", label: "GoLive"        },
    "?":{ bg: "002F5E", label: "Meilenstein"  }
  },
  fte: {
    high: { bg: "F5C8D7", text: "960A3C" },
    mid2: { bg: "EBCDF0", text: "781E8C" },
    mid1: { bg: "C8E1F5", text: "0A55B9" },
    low:  { bg: "DCF5FA", text: "147898" },
    zero: { bg: "FFFFFF", text: "C0C8D4" }
  }
};

// Dynamische Monate aus JSON (VBA exportiert config.monate); Fallback auf Hardcode
const MONATE = (config.monate && config.monate.length > 0)
  ? config.monate
  : ["Apr 26","Mai 26","Jun 26","Jul 26","Aug 26","Sep 26",
     "Okt 26","Nov 26","Dez 26","Jan 27","Feb 27","Mrz 27","Apr 27","Mai 27"];

function fteColor(val) {
  if (!val || val === 0) return CI.fte.zero;
  if (val > 2)           return CI.fte.high;
  if (val >= 1.5)        return CI.fte.mid2;
  if (val >= 1)          return CI.fte.mid1;
  return CI.fte.low;
}

// =========================================================================
// LAYOUT A: Projektfolie / Kapitelfolie
// Weißer Titel auf Navy-Balken (wie "Agenda Verlauf 1SP" / Bild 2)
// =========================================================================
function addFrameNavy(pres, slide, title, pageNum) {
  // Weißer Hintergrund (Header-Bereich bleibt weiß für CI-konformes Logo)
  slide.background = { color: CI.white };

  // 1. Hellblauer Content-Bereich (endet vor Footer-Gradient)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: L.navyH, w: L.W, h: L.footerY - L.navyH,
    fill: { color: CI.bgLight }, line: { color: CI.bgLight, width: 0 }
  });
  // Weißer Streifen nach dem Gradient bis Folienende
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: L.footerY + L.footerH, w: L.W, h: L.H - L.footerY - L.footerH,
    fill: { color: CI.white }, line: { color: CI.white, width: 0 }
  });

  // 2. Navy-Balken oben – endet vor Logo
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 8.15, h: L.navyH,
    fill: { color: CI.navy }, line: { color: CI.navy, width: 0 }
  });

  // 3. Logo auf weißem Hintergrund (CI-konform)
  slide.addImage({ data: LOGO_B64, x: L.logoX, y: L.logoY, w: L.logoW, h: L.logoH });

  // 4. Titel: WEISS auf Navy
  slide.addText(title, {
    x: L.titleX, y: L.titleY, w: 7.6, h: L.titleH,
    fontSize: 18, fontFace: "Calibri", bold: true,
    color: CI.white, valign: "middle", margin: 0
  });

  // 5. Footer-Verlaufsstreifen
  slide.addImage({ data: FOOTER_B64, x: L.footerX, y: L.footerY, w: L.footerW, h: L.footerH });

  // 6. Copyright + Seitenzahl
  slide.addText("© PureLoX SOLUTIONS", {
    x: L.copyrightX, y: L.copyrightY, w: 1.8, h: L.copyrightH,
    fontSize: 7, fontFace: "Calibri", color: "808080", margin: 0
  });
  if (pageNum) {
    slide.addText(String(pageNum), {
      x: L.pageNumX, y: L.pageNumY, w: L.pageNumW, h: L.pageNumH,
      fontSize: 7, fontFace: "Calibri", color: "808080", align: "right", margin: 0
    });
  }
}

// =========================================================================
// LAYOUT B: Übersichtsfolie / "Leer"-Layout
// Navy-Text auf weißem Hintergrund (wie Bild 1 / Gesamtübersicht)
// =========================================================================
function addFrameLight(pres, slide, title, pageNum) {
  // Weißer Hintergrund
  slide.background = { color: CI.white };

  // 1. Hellblauer Content-Bereich (endet vor Footer-Gradient)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: L.navyH, w: L.W, h: L.footerY - L.navyH,
    fill: { color: CI.bgLight }, line: { color: CI.bgLight, width: 0 }
  });
  // Weißer Streifen nach dem Gradient bis Folienende
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: L.footerY + L.footerH, w: L.W, h: L.H - L.footerY - L.footerH,
    fill: { color: CI.white }, line: { color: CI.white, width: 0 }
  });

  // 2. Logo oben rechts (auf weißem Hintergrund)
  slide.addImage({ data: LOGO_B64, x: L.logoX, y: L.logoY, w: L.logoW, h: L.logoH });

  // 3. Titel: NAVY-TEXT auf weißem Hintergrund
  slide.addText(title, {
    x: L.titleX, y: L.titleY, w: 7.6, h: L.titleH,
    fontSize: 18, fontFace: "Calibri", bold: true,
    color: CI.navy, valign: "middle", margin: 0
  });

  // 4. Footer-Verlaufsstreifen
  slide.addImage({ data: FOOTER_B64, x: L.footerX, y: L.footerY, w: L.footerW, h: L.footerH });

  // 5. Copyright + Seitenzahl
  slide.addText("© PureLoX SOLUTIONS", {
    x: L.copyrightX, y: L.copyrightY, w: 1.8, h: L.copyrightH,
    fontSize: 7, fontFace: "Calibri", color: "808080", margin: 0
  });
  if (pageNum) {
    slide.addText(String(pageNum), {
      x: L.pageNumX, y: L.pageNumY, w: L.pageNumW, h: L.pageNumH,
      fontSize: 7, fontFace: "Calibri", color: "808080", align: "right", margin: 0
    });
  }
}

// Alias für Abwärtskompatibilität
function addFrame(pres, slide, title, pageNum) {
  addFrameNavy(pres, slide, title, pageNum);
}

// =========================================================================
// PRÄSENTATION
// =========================================================================
const pres = new pptxgen();
pres.layout  = "LAYOUT_16x9";
pres.title   = config.titelseite.headline;
pres.author  = config.titelseite.ersteller || "PureLoX SOLUTIONS";
pres.company = "PureLoX SOLUTIONS GmbH";

// =========================================================================
// FOLIE 1: TITELSEITE (exakt nach Original-Template slideLayout2)
// =========================================================================
const slideT = pres.addSlide();

// 1. Hintergrundbild (Roboter/"1" – volle Folie)
slideT.addImage({ data: TITLEBG_B64, x: 0, y: 0, w: 10, h: 5.627 });

// 2. Wolken unten rechts
slideT.addImage({ data: CLOUDS_B64, x: 3.655, y: 4.561, w: 5.043, h: 1.065 });

// 3. Logo oben rechts (weißes Logo auf blauem Hintergrund)
slideT.addImage({ data: LOGOWHITE_B64, x: 8.035, y: 0.240, w: 1.683, h: 0.505 });

// 4. Headline (weiß, fett)
slideT.addText(config.titelseite.headline, {
  x: 0.543, y: 0.894, w: 3.975, h: 0.827,
  fontSize: 32, fontFace: "Calibri", bold: true,
  color: CI.white, valign: "top", margin: 0
});

// 5. Subheadline (hellblau/cyan, fett)
if (config.titelseite.subheadline) {
  slideT.addText(config.titelseite.subheadline, {
    x: 0.543, y: 1.850, w: 3.975, h: 1.102,
    fontSize: 18, fontFace: "Calibri", bold: true,
    color: "00B4D8", valign: "top", margin: 0
  });
}

// 6. "Präsentation für" Box (weißer Hintergrund, PLX-Logo oder Kundenname)
if (config.titelseite.praesentationFuer) {
  // Weißer Kasten
  slideT.addShape(pres.shapes.RECTANGLE, {
    x: 0.20, y: 3.75, w: 3.50, h: 1.65,
    fill: { color: CI.white }, line: { color: CI.white, width: 0 }
  });
  // "PRÄSENTATION FÜR" Label
  slideT.addText("PRÄSENTATION FÜR", {
    x: 0.33, y: 3.83, w: 3.2, h: 0.22,
    fontSize: 9, fontFace: "Calibri", bold: true,
    color: CI.navy, margin: 0
  });
  // PLX-Logo in der Box (falls Kundenname = PLX, Logo zeigen; sonst Text)
  slideT.addImage({ data: LOGO_B64, x: 0.33, y: 4.08, w: 2.10, h: 0.64 });
}

// 7. Datum & Ersteller (dezent)
slideT.addText(`${config.titelseite.datum || ""}  |  ${config.titelseite.ersteller || ""}`, {
  x: 0.35, y: 5.38, w: 7, h: 0.20,
  fontSize: 8, fontFace: "Calibri", color: "BBCCDD", margin: 0
});

// =========================================================================
// FOLIE 2: LEGENDE
// =========================================================================
const slideL = pres.addSlide();
addFrameLight(pres, slideL, "Legende & Anleitung", 2);

const LY = L.contentY;
const legendRows = [
  [{ text:"Phase", options:{bold:true,color:CI.white,fill:{color:CI.navy},fontSize:9}},
   { text:"Kürzel",options:{bold:true,color:CI.white,fill:{color:CI.navy},align:"center",fontSize:9}},
   { text:"Balkenfarbe",options:{bold:true,color:CI.white,fill:{color:CI.navy},fontSize:9}}],
  [{ text:"Pflichtenheft",options:{fontSize:10}},{text:"p",options:{align:"center",bold:true,color:CI.phase.p.bg,fontSize:10}},{text:"",options:{fill:{color:CI.phase.p.bg}}}],
  [{ text:"Konfiguration",options:{fontSize:10}},{text:"k",options:{align:"center",bold:true,color:CI.phase.k.bg,fontSize:10}},{text:"",options:{fill:{color:CI.phase.k.bg}}}],
  [{ text:"Test",         options:{fontSize:10}},{text:"t",options:{align:"center",bold:true,color:CI.phase.t.bg,fontSize:10}},{text:"",options:{fill:{color:CI.phase.t.bg}}}],
  [{ text:"GoLive",       options:{fontSize:10}},{text:"g",options:{align:"center",bold:true,color:CI.phase.g.bg,fontSize:10}},{text:"",options:{fill:{color:CI.phase.g.bg}}}],
  [{ text:"Meilenstein",  options:{fontSize:10}},{text:"?",options:{align:"center",bold:true,color:CI.white,fill:{color:CI.phase["?"].bg},fontSize:10}},{text:"",options:{fill:{color:CI.phase["?"].bg}}}],
];
slideL.addTable(legendRows, {
  x: 0.35, y: LY, w: 4.5, h: legendRows.length * 0.36, colW:[1.9,0.8,1.8],
  border:{pt:0,color:"FFFFFF"}, fontFace:"Calibri", color:CI.text,
  fill:{color:CI.white}, rowH: 0.36
});

slideL.addText("FTE Auslastung (Heatmap)", {
  x: 5.3, y: LY, w:4.2, h:0.32, fontSize:11, fontFace:"Calibri", bold:true, color:CI.navy
});
const hR = [
  [{text:"> 2 FTE",     options:{fill:{color:CI.fte.high.bg},color:CI.fte.high.text,bold:true,fontSize:10}}],
  [{text:"1.5 – 2 FTE", options:{fill:{color:CI.fte.mid2.bg},color:CI.fte.mid2.text,fontSize:10}}],
  [{text:"1 – 1.5 FTE", options:{fill:{color:CI.fte.mid1.bg},color:CI.fte.mid1.text,fontSize:10}}],
  [{text:"0 – 1 FTE",   options:{fill:{color:CI.fte.low.bg}, color:CI.fte.low.text, fontSize:10}}],
  [{text:"0 / leer",    options:{fill:{color:"F0F4FA"},color:"9AAABB",fontSize:10}}],
];
slideL.addTable(hR, {
  x:5.3, y:LY+0.38, w:3.8, h: hR.length * 0.33,
  border:{pt:0,color:"FFFFFF"}, fontFace:"Calibri", rowH:0.33
});

// =========================================================================
// PROJEKT-FOLIEN: Gantt als Farbbalken + FTE
// =========================================================================
const projekte = config.projekte || [];
const phasenOrder = ["p","k","t","g","?"];
const tW  = L.contentW;            // Tabellenbreite
const lbW = 1.45;                  // Label-Spalte
const mW  = (tW - lbW) / MONATE.length;  // Monats-Spaltenbreite
const colW = [lbW, ...Array(MONATE.length).fill(mW)];

let pageCounter = 3;
projekte.forEach((proj, idx) => {
  const tX    = L.contentX;
  const ganttY = L.navyH + 0.09;

  // Aktive TPs (mit Daten); Fallback auf altes JSON-Format ohne teilprojekte
  const allTPs = proj.teilprojekte || [];
  const activeTPs = allTPs.filter(tp =>
    Object.keys(tp.phasen || {}).length > 0 || Object.keys(tp.fte || {}).length > 0
  );
  const useLegacy = activeTPs.length === 0 && (proj.phasen || proj.fte);
  const renderTPs = useLegacy
    ? [{ name: proj.name || "Gesamt", phasen: proj.phasen || {}, fte: proj.fte || {} }]
    : activeTPs;

  const nTPs = renderTPs.length;

  // Nur befüllte Phasen pro TP ermitteln
  const tpActivePhases = renderTPs.map(tp =>
    phasenOrder.filter(ph => MONATE.some(m => (tp.phasen || {})[m] === ph))
  );

  // Für Gantt: nur TPs die mindestens eine befüllte Phase haben
  const ganttTPs = renderTPs
    .map((tp, i) => ({ tp, phases: tpActivePhases[i], origIdx: i }))
    .filter(({ phases }) => phases.length > 0);

  // Zeilenanzahl: Kopfzeile + pro Gantt-TP: 1 Header + nur befüllte Phasen-Zeilen
  const ganttNRows = 1 + ganttTPs.reduce((s, { phases }) => s + 1 + phases.length, 0);
  const fteNRows   = 1 + nTPs + 1;
  const labelGap   = 0.18;

  // Passt alles auf eine Folie? Wenn nicht → Zwei-Folien-Layout
  const availH_single = L.footerY - ganttY - labelGap - 0.04;
  const rowH_single   = Math.min(0.38, availH_single / (ganttNRows + fteNRows));
  const useTwoSlides  = nTPs >= 3 || rowH_single < 0.24;

  // --- Gantt-Folie rendern: addShape/addText für exakte Y-Positionierung ---
  const renderGantt = (targetSlide, rH, rFontSize, startY) => {
    const pillRowYMap = new Map(); // "origIdx-ph" → exakte Y-Position der Zeile
    const pillPadX = 0.02;
    let curY = startY;

    // Monats-Kopfzeile (Navy)
    targetSlide.addShape(pres.shapes.RECTANGLE, {
      x: tX, y: curY, w: tW, h: rH,
      fill: { color: CI.navy }, line: { color: CI.navy, width: 0 }
    });
    MONATE.forEach((m, mIdx) => {
      targetSlide.addText(m, {
        x: tX + lbW + mIdx * mW, y: curY, w: mW, h: rH,
        color: CI.white, fontSize: rFontSize, fontFace: "Calibri", bold: true,
        align: "center", valign: "middle", margin: 0
      });
    });
    curY += rH;

    // TP-Gruppen (nur TPs mit Phasen-Daten, nur befüllte Phasen)
    ganttTPs.forEach(({ tp, phases, origIdx }) => {
      targetSlide.addShape(pres.shapes.RECTANGLE, {
        x: tX, y: curY, w: tW, h: rH,
        fill: { color: "D4DEEC" }, line: { color: "D4DEEC", width: 0 }
      });
      targetSlide.addText(tp.name || `Teilprojekt ${origIdx + 1}`, {
        x: tX + 0.06, y: curY, w: lbW - 0.06, h: rH,
        color: CI.navy, fontSize: rFontSize, fontFace: "Calibri", bold: true,
        valign: "middle", margin: 0
      });
      curY += rH;

      phases.forEach(ph => {
        targetSlide.addShape(pres.shapes.RECTANGLE, {
          x: tX, y: curY, w: tW, h: rH,
          fill: { color: CI.white }, line: { color: CI.white, width: 0 }
        });
        targetSlide.addText("  " + (CI.phase[ph]?.label || ph), {
          x: tX, y: curY, w: lbW, h: rH,
          color: CI.text, fontSize: rFontSize, fontFace: "Calibri",
          valign: "middle", margin: 0
        });
        pillRowYMap.set(`${origIdx}-${ph}`, curY);
        curY += rH;
      });
    });

    // Pills: Y direkt aus pillRowYMap – nie separat berechnet
    renderTPs.forEach((tp, tpIdx) => {
      MONATE.forEach((m, mIdx) => {
        const phasenVal = (tp.phasen || {})[m];
        const keys = Array.isArray(phasenVal) ? phasenVal : (phasenVal ? [phasenVal] : []);
        keys.forEach(key => {
          if (!CI.phase[key]) return;
          const rowY = pillRowYMap.get(`${tpIdx}-${key}`);
          if (rowY === undefined) return;
          const pillH    = rH * 0.68;
          const pillOffY = (rH - pillH) / 2;
          targetSlide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
            x: tX + lbW + mIdx * mW + pillPadX,
            y: rowY + pillOffY,
            w: mW - 2 * pillPadX,
            h: pillH,
            fill: { color: CI.phase[key].bg },
            line: { color: CI.phase[key].bg, width: 0 },
            rectRadius: pillH / 2
          });
        });
      });
    });
  };

  // --- FTE-Folie rendern ---
  const renderFte = (targetSlide, rH, rFontSize, startY) => {
    targetSlide.addText("Kapazitätsplanung (FTE)", {
      x: tX, y: startY - labelGap, w: 4, h: labelGap,
      fontSize: 8, fontFace: "Calibri", bold: true, color: "7888A0", margin: 0
    });

    const fteHeader = [{ text:"", options:{ fill:{color:CI.navy}, color:CI.white, bold:true, fontSize:rFontSize, valign:"middle" }}];
    MONATE.forEach(m => fteHeader.push({ text:m, options:{ fill:{color:CI.navy}, color:CI.white, bold:true, align:"center", valign:"middle", fontSize:rFontSize }}));

    const fteTableRows = [fteHeader];
    renderTPs.forEach(tp => {
      const tpFte = tp.fte || {};
      const row = [{ text: tp.name || "", options:{ color:CI.text, fontSize:rFontSize, align:"left", valign:"middle" }}];
      MONATE.forEach(m => {
        const val = tpFte[m] || 0;
        const c = fteColor(val);
        row.push({ text: val > 0 ? String(val) : "", options:{ fill:{color:c.bg}, color:c.text, align:"center", valign:"middle", bold:val>=1.5, fontSize:rFontSize }});
      });
      fteTableRows.push(row);
    });

    const fteSumme = proj.fteSumme || (useLegacy ? proj.fte || {} : {});
    const sumRow = [{ text:"SUMME", options:{ fill:{color:CI.navy}, color:CI.white, bold:true, fontSize:rFontSize, valign:"middle" }}];
    MONATE.forEach(m => {
      const val = fteSumme[m] || 0;
      const c = fteColor(val);
      sumRow.push({ text: val > 0 ? String(val) : "0",
        options:{ fill:{color:val>0?c.bg:CI.navy}, color:val>0?c.text:CI.white, align:"center", valign:"middle", bold:true, fontSize:rFontSize }});
    });
    fteTableRows.push(sumRow);

    targetSlide.addTable(fteTableRows, {
      x: tX, y: startY, w: tW, h: fteTableRows.length * rH, colW,
      rowH: rH,
      border:{ pt:0.3, color:"D0D8E4" },
      fontFace:"Calibri", color:CI.text,
      fill:{ color:CI.white }
    });
  };

  if (useTwoSlides) {
    // === Folie A: Gantt ===
    const slideA = pres.addSlide();
    addFrameLight(pres, slideA, proj.name || `Projekt ${idx+1}`, pageCounter++);
    const availH_gantt = L.footerY - ganttY - 0.04;
    const rowH_A       = Math.min(0.40, availH_gantt / ganttNRows);
    const fontSize_A   = rowH_A >= 0.22 ? 8 : 7;
    renderGantt(slideA, rowH_A, fontSize_A, ganttY);

    // === Folie B: Kapazitätsplanung (FTE) ===
    const slideB = pres.addSlide();
    addFrameLight(pres, slideB, (proj.name || `Projekt ${idx+1}`) + " – Kapazitätsplanung", pageCounter++);
    const availH_fte = L.footerY - ganttY - labelGap - 0.06;
    const rowH_B     = Math.min(0.70, Math.max(0.25, availH_fte / fteNRows));
    const fontSize_B = rowH_B >= 0.45 ? 10 : rowH_B >= 0.22 ? 8 : 7;
    renderFte(slideB, rowH_B, fontSize_B, ganttY + labelGap);

  } else {
    // === Einzelfolie: Gantt + FTE ===
    const slide = pres.addSlide();
    addFrameLight(pres, slide, proj.name || `Projekt ${idx+1}`, pageCounter++);
    const rowH    = rowH_single;
    const fontSize = rowH >= 0.20 ? 8 : 7;
    renderGantt(slide, rowH, fontSize, ganttY);
    const fteY = ganttY + ganttNRows * rowH + labelGap;
    renderFte(slide, rowH, fontSize, fteY);
  }
});

// =========================================================================
// GESAMTÜBERSICHT
// Skaliert Zeilenhöhe UND Schriftgröße dynamisch und verteilt sich bei
// vielen Projekten (z.B. > 12-15) automatisch auf mehrere Folien, damit
// die FTE-Zusammenfassung immer lesbar bleibt statt gestaucht zu werden.
// =========================================================================
const tX2  = L.contentX;
const tW2  = L.contentW;
const lbW2 = 1.4;
const mW2  = (tW2 - lbW2) / MONATE.length;
const colW2 = [lbW2, ...Array(MONATE.length).fill(mW2)];

const availH   = L.footerY - L.contentY - 0.1;
const MIN_ROWH2  = 0.22;   // kleinste noch lesbare Zeilenhöhe
const MIN_FONT2  = 7;      // kleinste noch lesbare Schriftgröße

// Portfolio-Summe je Monat (über ALLE Projekte, unabhängig von der Seitenaufteilung)
const sums = {};
MONATE.forEach(m => sums[m] = 0);
projekte.forEach(proj => {
  MONATE.forEach(m => { sums[m] += (proj.fteSumme || proj.fte || {})[m] || 0; });
});

// Wie viele Projekt-Zeilen passen pro Folie? (abzüglich Kopfzeile + Summenzeile
// auf der letzten Folie, damit auch diese garantiert noch in availH passt)
const maxRowsPerSlide = Math.max(1, Math.floor(availH / MIN_ROWH2) - 2);

const gesamtPages = [];
if (projekte.length === 0) {
  gesamtPages.push([]);
} else {
  for (let i = 0; i < projekte.length; i += maxRowsPerSlide) {
    gesamtPages.push(projekte.slice(i, i + maxRowsPerSlide));
  }
}

gesamtPages.forEach((pageProjekte, pageIdx) => {
  const isLastPage = pageIdx === gesamtPages.length - 1;
  const slideG = pres.addSlide();
  const titleG = gesamtPages.length > 1
    ? `Kapazitätsübersicht – Gesamt (${pageIdx + 1}/${gesamtPages.length})`
    : "Kapazitätsübersicht – Gesamt";
  addFrameLight(pres, slideG, titleG, pageCounter++);

  const rowsOnSlide = pageProjekte.length + 1 + (isLastPage ? 1 : 0); // Header (+ Summe)
  const rowH2    = Math.max(MIN_ROWH2, Math.min(0.38, availH / rowsOnSlide));
  const fontSize2 = rowH2 >= 0.32 ? 9 : rowH2 >= 0.26 ? 8 : MIN_FONT2;

  const gHeader2 = [{ text:"Projekt", options:{fill:{color:CI.navy},color:CI.white,bold:true,fontSize:fontSize2,valign:"middle"}}];
  MONATE.forEach(m => gHeader2.push({
    text:m, options:{fill:{color:CI.navy},color:CI.white,bold:true,align:"center",valign:"middle",fontSize:fontSize2}
  }));

  const gesamtRows = [gHeader2];
  pageProjekte.forEach(proj => {
    const row = [{ text:proj.name, options:{color:CI.text,fontSize:fontSize2,valign:"middle"}}];
    MONATE.forEach(m => {
      const val = (proj.fteSumme||proj.fte||{})[m] || 0;
      const c = fteColor(val);
      row.push({ text: val>0?String(val):"",
        options:{ fill:{color:c.bg}, color:c.text, align:"center", valign:"middle", bold:val>=1.5, fontSize:fontSize2 }});
    });
    gesamtRows.push(row);
  });

  if (isLastPage) {
    const sumG = [{ text:"GESAMT", options:{fill:{color:CI.navy},color:CI.white,bold:true,fontSize:fontSize2,valign:"middle"}}];
    MONATE.forEach(m => {
      const val = Math.round(sums[m]*10)/10;
      const c = fteColor(val);
      sumG.push({ text: val>0?String(val):"0",
        options:{ fill:{color:c.bg}, color:c.text, align:"center", valign:"middle", bold:true, fontSize:fontSize2 }});
    });
    gesamtRows.push(sumG);
  }

  slideG.addTable(gesamtRows, {
    x: tX2, y: L.contentY, w: tW2, h: gesamtRows.length * rowH2, colW: colW2, rowH: rowH2,
    border:{pt:0.3,color:"D0D8E4"}, fontFace:"Calibri", color:CI.text,
    fill:{color:CI.white}
  });
});

// =========================================================================
// AUSGABE
// =========================================================================
const outFile = process.argv[3] || "PLX_Kapazitaetsplanung.pptx";
pres.writeFile({ fileName: outFile }).then(() => {
  console.log("PPTX erstellt:", outFile);
}).catch(err => { console.error("Fehler:", err); process.exit(1); });
